SELECT t.Team_Name FROM dbo.HS_Team_Names t WHERE t.Team_Name IN ('Eldorado (OK)','Eldorado (TX)','Kiowa (OK)','Shawnee (OK)','Ada (KS)','Chesnee (SC)','Marshall (OK)','Fort Smith (AR)','Springdale (AR)','Chetopa (KS)','Fayetteville (AR)','Foreman (AR)','Frontenac (KS)','Galena (KS)','Gentry (AR)','Gravette (AR)','Hackett (AR)','Hugoton (KS)','Independence (KS)','Lincoln (AR)','Prairie Grove (AR)','Riverton (KS)','Rogers (AR)','Russellville (AR)','Sarcoxie (MO)','Van Buren (AR)','Gruver (TX)','Pampa (TX)','Spearman (TX)','Sunray (TX)','Booker (TX)','Morse (TX)','Eureka (KS)','Decatur (AR)','Clovis (NM)','Sulphur (OK)','Wilson (OK)','Perry (OK)')
 OR t.Team_Name LIKE '%Pawnee (CO)' ORDER BY 1;
